/* Hearts and Minds witness layer — first-person evidence cards.
   One witness per moment. Every stat carries its source. Generated 12 Jun 2026. */
(function(){
var IMG = "../assets/personas/";
var PERSONA = {"sarah": "DTx OM - Persona Sarah.html", "priya": "DTx OM - Persona Priya.html", "aisha": "DTx OM - Persona Aisha.html", "adam": "DTx OM - Persona Adam.html", "catherine": "DTx OM - Persona Catherine.html", "joe": "DTx OM - Persona Joe.html", "anita": "DTx OM - Persona Anita.html", "hannah": "DTx OM - Persona Hannah.html", "ngozi": "DTx OM - Persona Ngozi.html", "david": "DTx OM - Persona David.html", "ravi": "DTx OM - Persona HealthStore prescribing clinician.html", "daniel": "DTx OM - Persona Daniel.html"};
var M = {"abdul-a1": {"who": "Sarah", "role": "Commissioner", "img": "sarah", "say": "Somewhere out there are 4.2 million people, England-wide, with high blood pressure nobody has found. Abdul found his own — with his phone. That is a stroke I never have to commission.", "stat": "An estimated 4.2 million adults in England have undiagnosed high blood pressure; hypertension is implicated in around half of all heart attacks and strokes.", "source": "NHS England / Office for National Statistics, 2025", "url": "https://www.england.nhs.uk/north-west/2025/09/04/are-you-one-of-the-missing-millions-get-your-blood-pressure-checked-this-know-your-numbers-week/"}, "abdul-a2": {"who": "Sarah", "role": "Commissioner", "img": "sarah", "say": "Eight million outpatient appointments were missed last year, and I paid for every empty room. A kit waiting on his kitchen table cannot be missed — only posted a day late.", "stat": "8.0 million outpatient appointments in England went unattended in 2023/24, of 135.4 million booked. NHS England costs a missed outpatient appointment at around £120 — roughly £1bn a year of clinical time.", "source": "NHS Digital, Hospital Outpatient Activity 2023-24; NHS England DNA costings", "url": "https://digital.nhs.uk/data-and-information/publications/statistical/hospital-outpatient-activity/2023-24"}, "abdul-a3": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "Thirty-nine million people already carry the front door in their pocket. I don't have to build Abdul a platform — I have to plug the kit into the one he already uses.", "stat": "39 million people are registered on the NHS App, with 62.3 million logins in a single month.", "source": "NHS England, December 2025", "url": "https://www.england.nhs.uk/2025/12/record-numbers-using-nhs-app-to-manage-health/"}, "abdul-a4": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "Threshold alerts replace periodic reviews. My attention goes where the readings say — not where the diary says.", "stat": "Follow-up appointments account for 54% of NHS outpatient activity in England, much of it judged of limited clinical value.", "source": "GIRFT / NHS England outpatient improvement guide", "url": "https://gettingitrightfirsttime.co.uk/outpatients/"}, "mark-a1": {"who": "Adam", "role": "Consultant urologist", "img": "adam", "say": "Prostate cancer is now the UK's most common cancer — more than sixty-four thousand men a year, and every one of them lands on a list like mine. The list grows. My clinic doesn't.", "stat": "64,000+ men diagnosed with prostate cancer in the UK per year (2022 data); around 6,500 a year choose active surveillance, with up to 5,000 more who could.", "source": "Prostate Cancer UK, 2026", "url": "https://prostatecanceruk.org/about-us/news-and-views/2026/01/prostate-most-common-cancer", "source2": "Prostate Cancer UK / NHS data, 2025", "url2": "https://prostatecanceruk.org/about-us/news-and-views/2025/08/active-surveillance-unnecessary-treatment"}, "mark-a2": {"who": "Catherine", "role": "Acute Trust commissioner", "img": "catherine", "say": "Follow-ups are fifty-four per cent of everything my outpatient budget buys. Mark's routine PSA is precisely the kind of follow-up that never needed a room.", "stat": "Follow-up appointments represent 54% of NHS outpatient activity; standardised templates and remote models could unlock 1–2 million slots.", "source": "GIRFT, Further Faster programme", "url": "https://gettingitrightfirsttime.co.uk/cross_cutting_theme/further-faster-programme/"}, "mark-a3": {"who": "Joe", "role": "Supplier", "img": "joe", "say": "One and a quarter billion pathology requests this year, growing five and a half per cent annually. Buildings can't absorb that curve — kit out, post back, lab capacity where it's actually elastic.", "stat": "NHS pathology test requests projected at 1.25bn for 2025/26 (730m in 2013/14), growing ~5.5% a year.", "source": "NHS national programme analysis, 2026"}, "mark-a4": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "The silence is doing clinical work. Every result is reviewed in trend, and escalation happens when the line moves — safety is the review, not the appointment.", "stat": "England booked 135.4 million outpatient appointments in 2023/24; routine surveillance bloods need not be among them.", "source": "NHS England, Hospital Outpatient Activity 2023-24"}, "layla-a1": {"who": "Anita", "role": "ICB / GP commissioner", "img": "anita", "say": "Fifteen million missed GP-practice appointments a year — £216 million — and the system writes DNA as if it were her fault. Layla wasn't refusing care. She was keeping her job.", "stat": "Around 15 million general-practice appointments are missed each year, costing the NHS £216m (average ~£30 per missed GP appointment).", "source": "NHS England, 2019", "url": "https://www.england.nhs.uk/2019/01/missed-gp-appointments-costing-nhs-millions/"}, "layla-a2": {"who": "Hannah", "role": "GP", "img": "hannah", "say": "Iron-deficiency anaemia touches around eight per cent of adult women, and the monitoring is one blood tube on a six-month clock. The clock was never the problem. The clinic was.", "stat": "Iron deficiency anaemia prevalence in the UK is around 3% of adult men and 8% of adult women; guidelines monitor treatment response by FBC.", "source": "NICE clinical knowledge summary", "url": "https://www.nhs.uk/conditions/iron-deficiency-anaemia/"}, "layla-a3": {"who": "Ngozi", "role": "Information Governance", "img": "ngozi", "say": "The result lands in her GP record, not in a silo — the same governance as any practice bloods. The kit changes the venue. It never changes the protections.", "stat": "DPIA, data-sharing and processing agreements are executed before go-live; the result flows to the GP record under the practice's existing controllership.", "source": "Service IG framework (executed pre-go-live)"}, "layla-a4": {"who": "Anita", "role": "ICB / GP commissioner", "img": "anita", "say": "Three hundred and seven million general-practice appointments a year, and one in twenty missed. Take even the routine bloods out of that queue and my access targets can finally breathe.", "stat": "~307 million general-practice sessions are scheduled annually in England; around 5% are missed without enough notice to rebook.", "source": "NHS England, 2019", "url": "https://www.england.nhs.uk/2019/01/missed-gp-appointments-costing-nhs-millions/"}, "sean-a1": {"who": "Hannah", "role": "GP", "img": "hannah", "say": "I run the annual health checks — uptake is nearly eighty per cent now. And still, people with a learning disability die a median nineteen and a half years younger than everyone else. The check exists because the gap is real. The bloods are where it stalls.", "stat": "79.9% of people on the learning disability register had an annual health check (March 2025); median age of death is 62.3 — about 19.5 years younger than the general population.", "source": "NHS England; LeDeR annual report 2023 (pub. 2025)", "url": "https://www.england.nhs.uk/learning-disabilities/improving-health/learning-from-lives-and-deaths/"}, "sean-a2": {"who": "His brother", "role": "Family", "img": null, "say": "Easy-read isn't a kindness we're asking for — it has been a legal duty since 2016. The Accessible Information Standard says information must work for the person it's about. For Sean, pictures work.", "stat": "The Accessible Information Standard has been a legal requirement for NHS and adult social care providers since 2016.", "source": "NHS England, Accessible Information Standard", "url": "https://www.england.nhs.uk/ourwork/accessibleinfo/"}, "sean-a3": {"who": "Ngozi", "role": "Information Governance", "img": "ngozi", "say": "The reasonable-adjustment flag exists nationally so Sean's needs travel with his record. Honouring it at the ordering step is the difference between a policy and a practice.", "stat": "The Reasonable Adjustment Digital Flag is a national NHS record flag enabling adjustments to be known across services.", "source": "NHS England, Reasonable Adjustment Digital Flag", "url": "https://www.england.nhs.uk/learning-disabilities/improving-health/reasonable-adjustments/"}, "sean-a4": {"who": "Sarah", "role": "Commissioner", "img": "sarah", "say": "Thirty-nine per cent of the deaths reviewed were judged avoidable. Avoidable is a commissioning word. Reach is the lever I hold — and this is what reach looks like.", "stat": "39% of reviewed deaths of people with a learning disability were assessed as avoidable (down from 46% in 2021).", "source": "LeDeR annual report 2023 (pub. 2025)", "url": "https://www.england.nhs.uk/learning-disabilities/improving-health/learning-from-lives-and-deaths/"}, "errol-s1": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "Errol isn't doing anything special — and that's the design. Thirty-nine million people already log into the NHS App; his readings ride rails that were already there.", "stat": "39 million people are registered on the NHS App, with 62.3 million logins in a single month.", "source": "NHS England, December 2025", "url": "https://www.england.nhs.uk/2025/12/record-numbers-using-nhs-app-to-manage-health/"}, "errol-s2": {"who": "Sarah", "role": "Commissioner", "img": "sarah", "say": "No review appointment would ever have caught this, Errol felt fine. When a smartwatch flags an irregular pulse, about a third of those people turn out to have atrial fibrillation on an ECG. In the months after a heart attack that is exactly the signal you cannot afford to miss. This is how you catch it.", "stat": "In the Apple Heart Study of 419,297 participants, 34% of those who received a smartwatch irregular-pulse notification had atrial fibrillation confirmed on subsequent ECG patch monitoring.", "source": "Perez et al, New England Journal of Medicine, 2019", "url": "https://www.nejm.org/doi/full/10.1056/NEJMoa1901183"}, "errol-s3": {"who": "Joe", "role": "Supplier", "img": "joe", "say": "Kidney function, lipids, HbA1c — two days from signal to doorstep. Try booking that through a system processing one and a quarter billion requests a year.", "stat": "NHS pathology test requests projected at 1.25bn for 2025/26 (730m in 2013/14), growing ~5.5% a year.", "source": "NHS national programme analysis, 2026"}, "errol-s4": {"who": "Ravi", "role": "Prescribing clinician", "img": "ravi", "say": "I prescribe the app the way I prescribe the tablets, and the evidence is there. Home-based cardiac rehab gives the same outcomes as the hospital gym for a patient like Errol, and the support is there at 2am when I am not. The difference is that he actually finishes it.", "stat": "A Cochrane review found home-based and centre-based cardiac rehabilitation produce equivalent clinical and health-related quality-of-life outcomes for low-risk patients after a heart attack or revascularisation.", "source": "McDonagh et al, Cochrane Database of Systematic Reviews, 2023", "url": "https://www.cochranelibrary.com/cdsr/doi/10.1002/14651858.CD007130.pub5/full"}, "errol-s5": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "Three signal streams, one record, and my attention goes where the data says. The old model would have given Errol two routine follow-ups and missed the thing that mattered.", "stat": "Follow-up appointments account for 54% of NHS outpatient activity in England, much of it judged of limited clinical value.", "source": "GIRFT / NHS England outpatient improvement guide", "url": "https://gettingitrightfirsttime.co.uk/outpatients/"}, "errol-s6": {"who": "Sarah", "role": "Commissioner", "img": "sarah", "say": "Eighteen months, no second event, no readmission, and rehab finished. Completing cardiac rehabilitation after a heart attack cuts cardiovascular deaths by around a quarter and keeps people out of hospital. Every Errol who finishes is a readmission I never have to buy.", "stat": "A Cochrane meta-analysis of 63 trials and 14,486 participants found exercise-based cardiac rehabilitation reduces cardiovascular mortality (relative risk 0.74, around a 26% reduction) and reduces hospital admissions.", "source": "Dibben et al, Cochrane Database of Systematic Reviews, 2021", "url": "https://www.cochranelibrary.com/cdsr/doi/10.1002/14651858.CD001800.pub4/full"}, "marcus-s1": {"who": "Joe", "role": "Supplier", "img": "joe", "say": "I have sold into the NHS for years, and the evidence was never the barrier. Nineteen per cent fewer GP appointments, and a product can still die in pilot number twelve. Marcus needed a route, not another reference site.", "stat": "Real-world evaluations: 19% fewer GP appointments for DTx use in COPD; 70% reduction in anxiety symptoms with digital sleep therapy.", "source": "Published RWE (MyMHealth evaluation; Oxford Sleepio trial)"}, "marcus-s2": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "One assurance bar, national terms, prices on the catalogue. I would rather steward one front door than fifty side deals, and so would every supplier worth admitting.", "stat": "39 million people are registered on the NHS App, with 62.3 million logins in a single month.", "source": "NHS England, December 2025", "url": "https://www.england.nhs.uk/2025/12/record-numbers-using-nhs-app-to-manage-health/"}, "marcus-s5": {"who": "Sarah", "role": "Commissioner", "img": "sarah", "say": "The first prescription looks small from the supplier side. From mine, remote support like this cut non-elective admissions by forty per cent in one evaluation. Every activation is risk coming off my book.", "stat": "A 40% reduction in non-elective admissions was reported under remote monitoring in an ICB evaluation.", "source": "ICB remote-monitoring evaluation, cited in national programme analysis"}, "marcus-s6": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "Admitted once, bought everywhere, with the evidence commitment running on. That is what a market looks like when the operating model does the work the pilots never could.", "stat": "Real-world evaluations: 19% fewer GP appointments for DTx use in COPD; 70% reduction in anxiety symptoms with digital sleep therapy.", "source": "Published RWE (MyMHealth evaluation; Oxford Sleepio trial)"}, "ravi-s1": {"who": "Catherine", "role": "Acute Trust commissioner", "img": "catherine", "say": "Eight million outpatient appointments went unattended last year. A daytime rehab programme she cannot attend would simply have been more of them. The options on Ravi's desk fail her, and they cost me money doing it.", "stat": "8.0 million outpatient appointments in England went unattended in 2023/24, of 135.4 million booked. NHS England costs a missed outpatient appointment at around £120 — roughly £1bn a year of clinical time.", "source": "NHS Digital, Hospital Outpatient Activity 2023-24; NHS England DNA costings", "url": "https://digital.nhs.uk/data-and-information/publications/statistical/hospital-outpatient-activity/2023-24"}, "ravi-s2": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "What moved Ravi was not marketing, it was cover. A conditional recommendation with the safety case complete, and the evidence underneath it is real: fewer appointments, better control.", "stat": "Real-world evaluations: 19% fewer GP appointments for DTx use in COPD; 70% reduction in anxiety symptoms with digital sleep therapy.", "source": "Published RWE (MyMHealth evaluation; Oxford Sleepio trial)"}, "ravi-s4": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "Ravi's cohort view exists because every prescription rides the same rails. Thirty-nine million people already log into the NHS App; his fifteen patients were never a special integration.", "stat": "39 million people are registered on the NHS App, with 62.3 million logins in a single month.", "source": "NHS England, December 2025", "url": "https://www.england.nhs.uk/2025/12/record-numbers-using-nhs-app-to-manage-health/"}, "ravi-s5": {"who": "Catherine", "role": "Acute Trust commissioner", "img": "catherine", "say": "Two consultants prescribing within a month is not an anecdote to me. Follow-ups are fifty-four per cent of everything my outpatient budget buys, and this is the demand curve starting to bend.", "stat": "Follow-up appointments represent 54% of NHS outpatient activity; standardised templates and remote models could unlock 1–2 million slots.", "source": "GIRFT, Further Faster programme", "url": "https://gettingitrightfirsttime.co.uk/cross_cutting_theme/further-faster-programme/"}, "sarah-s1": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "Eighteen months and three procurements is the old price of a detection gap. The framework exists so that Sarah's question is which configuration, not which procurement.", "stat": "An estimated 4.2 million adults in England have undiagnosed high blood pressure; hypertension is implicated in around half of all heart attacks and strokes.", "source": "NHS England / Office for National Statistics, 2025", "url": "https://www.england.nhs.uk/north-west/2025/09/04/are-you-one-of-the-missing-millions-get-your-blood-pressure-checked-this-know-your-numbers-week/"}, "sarah-s3": {"who": "Ngozi", "role": "Information Governance", "img": "ngozi", "say": "IG fit is a question Sarah answers before she buys, not after she deploys. The DPIA, sharing and processing agreements are inherited from the framework and executed before go-live, every time.", "stat": "DPIA, data-sharing and processing agreements are executed before go-live as part of the framework's inherited IG artefact stack.", "source": "Service IG framework (executed pre-go-live)"}, "sarah-s5": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "One MI feed and one supplier-performance view, because the integration happened once, nationally. Her cohort walked in through a front door thirty-nine million people already use.", "stat": "39 million people are registered on the NHS App, with 62.3 million logins in a single month.", "source": "NHS England, December 2025", "url": "https://www.england.nhs.uk/2025/12/record-numbers-using-nhs-app-to-manage-health/"}, "sarah-s6": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "Detection up, admissions down, one set of numbers. Remote models cut non-elective admissions by forty per cent in one evaluation. That is the line I take to the next commissioner.", "stat": "A 40% reduction in non-elective admissions was reported under remote monitoring in an ICB evaluation.", "source": "ICB remote-monitoring evaluation, cited in national programme analysis"}, "sarah-s2": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "Eighteen months and a clean-sheet procurement is the old price of standing up an HIV self-test service. The framework is the new price, call-off terms, admitted suppliers, templates ready. The price of entry is a signature, not a discovery exercise.", "stat": "Bespoke OJEU-compliant procurement of a new service typically takes 6-9 months at minimum; call-off against an inherited national framework (e.g. SBS Lot 1) typically completes in weeks.", "source": "NHS SBS framework guidance (timing reflects commercial-experience baseline; specific durations not published on the SBS frameworks page)"}, "sarah-s4": {"who": "Joe", "role": "Supplier", "img": "joe", "say": "Every LA that calls off saves me the bespoke contract negotiation I would otherwise run separately. The same DSA, the same DPIA, the same clinical safety case, written once nationally, executed many times locally. The supplier-side win is the same as the commissioner-side win.", "stat": "Per-supplier bespoke contracts historically take 3-6 months per LA to negotiate. Inherited framework templates remove most of this overhead.", "source": "NHS SBS framework guidance (timing reflects commercial-experience baseline; specific durations not published on the SBS frameworks page)"}, "adam-s1": {"who": "Adam", "role": "Consultant urologist", "img": "adam", "say": "The patients I cannot see are the patients I lose. Prostate cancer is now the UK's most common cancer, more than sixty-four thousand men a year. The cohort grows. My clinic does not. The drop-outs are the ones I worry about most.", "stat": "64,000+ men diagnosed with prostate cancer in the UK per year (2022 data); around 6,500 a year choose active surveillance, with up to 5,000 more who could.", "source": "Prostate Cancer UK, 2026", "url": "https://prostatecanceruk.org/about-us/news-and-views/2026/01/prostate-most-common-cancer", "source2": "Prostate Cancer UK / NHS data, 2025", "url2": "https://prostatecanceruk.org/about-us/news-and-views/2025/08/active-surveillance-unnecessary-treatment"}, "adam-s2": {"who": "Catherine", "role": "Acute Trust commissioner", "img": "catherine", "say": "Follow-ups are fifty-four per cent of everything my outpatient budget buys. Adam's quarterly PSA review is precisely the kind of follow-up that never needed a room. Eight million outpatient appointments went unattended last year, and I paid for every empty slot.", "stat": "Follow-up appointments represent 54% of NHS outpatient activity; 8.0m appointments in England went unattended in 2023/24; standardised templates and remote models could unlock 1-2 million slots.", "source": "GIRFT, Further Faster programme; NHS Digital Hospital Outpatient Activity 2023-24", "url": "https://gettingitrightfirsttime.co.uk/cross_cutting_theme/further-faster-programme/"}, "adam-s3": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "The clinical role is preserved because the result returns to Adam first, in trend, with threshold alerts wired to NICE NG131. The kit changes the venue. The clinical decision authority does not move. That is the safety case.", "stat": "NICE NG131 covers PSA testing thresholds and surveillance triggers; clinical safety case (DCB0129/0160) executed pre-go-live for the configuration.", "source": "NICE NG131; NHS Digital DCB0129 / DCB0160", "url": "https://www.nice.org.uk/guidance/ng131"}, "adam-s4": {"who": "Mark", "role": "His patient", "img": "mark", "say": "Adam asked me at the end of the appointment if I would be comfortable doing the next blood at home. I said yes before he finished the sentence. The kit arrived. I took the sample on the date the clinic would have happened. The next clinic appointment was the one I actually needed.", "stat": "Around 6,500 men a year currently choose active surveillance for prostate cancer in the UK; up to 5,000 more are eligible. Drop-out from surveillance is a recognised clinical problem.", "source": "Prostate Cancer UK; NICE NG131", "url": "https://prostatecanceruk.org/about-us/news-and-views/2026/01/prostate-most-common-cancer"}, "adam-s5": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "Adam's cohort dashboard exists because every result writes back to the EPR cleanly. Trends arrive in his inbox without a clerk in the loop. Thirty-nine million people already log into the NHS App; this is the data layer his cohort already lives in.", "stat": "39 million people are registered on the NHS App, with 62.3 million logins in a single month; result write-back to the Trust EPR is part of the inherited platform integration.", "source": "NHS England, December 2025", "url": "https://www.england.nhs.uk/2025/12/record-numbers-using-nhs-app-to-manage-health/"}, "adam-s6": {"who": "Adam", "role": "Consultant urologist", "img": "adam", "say": "More patients in surveillance. Fewer drop-outs. Same team. The clinic now holds the patients whose disease behaviour says clinic is the right venue. Pathology test volumes nationally are growing at five and a half per cent a year; the buildings cannot absorb that curve, but the cohort can stay safe anyway.", "stat": "NHS pathology test requests projected at 1.25bn for 2025/26 (730m in 2013/14), growing ~5.5% a year. Remote surveillance with threshold alerts is a proven mechanism for holding active surveillance cohorts without clinic-capacity penalty.", "source": "NHS national programme analysis, 2026; clinical practice patterns"}, "hannah-s1": {"who": "Hannah", "role": "GP partner", "img": "hannah", "say": "Iron-deficiency anaemia touches around eight per cent of adult women. The monitoring is one blood tube on a six-month clock. The clock was never the problem. The clinic was. The patients I lose are the ones the clinic was always going to lose.", "stat": "Iron deficiency anaemia prevalence in UK adult women is around 8%; routine monitoring is typically a 6-month FBC cycle.", "source": "NICE clinical knowledge summary; NHS guidance", "url": "https://cks.nice.org.uk/topics/anaemia-iron-deficiency/"}, "hannah-s2": {"who": "Anita", "role": "ICB / GP commissioner", "img": "anita", "say": "Fifteen million missed GP appointments a year. Two hundred and sixteen million pounds. The system writes DNA as if it were the patient&apos;s fault. They were keeping their job. The clinic was always the wrong venue for routine bloods.", "stat": "Around 15 million general-practice appointments are missed each year, costing the NHS £216m (average ~£30 per missed GP appointment).", "source": "NHS England, 2019", "url": "https://www.england.nhs.uk/2019/01/missed-gp-appointments-costing-nhs-millions/"}, "hannah-s3": {"who": "Ngozi", "role": "Information Governance", "img": "ngozi", "say": "The result writes back to the GP record under the practice&apos;s existing controllership. DPIA, data-sharing and processing agreements execute before go-live. The kit changes the venue. It does not change the protections.", "stat": "DPIA, DSA and DPA are executed pre-go-live; the home-test result flows to the GP record under the practice&apos;s existing controllership.", "source": "Service IG framework (executed pre-go-live)"}, "hannah-s4": {"who": "Layla", "role": "Hannah&apos;s patient", "img": "layla", "say": "Hannah asked me at the end of the appointment if I would be comfortable doing the next FBC at home. I said yes before she finished the sentence. The kit arrived. I took the sample on a Saturday. The next appointment was the one I actually needed.", "stat": "Around 8% of UK adult women have iron deficiency anaemia; routine FBC monitoring is the standard treatment-response measurement.", "source": "NICE clinical knowledge summary", "url": "https://cks.nice.org.uk/topics/anaemia-iron-deficiency/"}, "hannah-s5": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "The result rides the same rails as any other blood. Result back to the GP record, in trend, on time. No parallel system, no clerk in the loop. Thirty-nine million people are already on the NHS App; the patient does not see infrastructure, just the kit.", "stat": "39 million people are registered on the NHS App, with 62.3 million logins in a single month; result write-back to the GP record is via the framework&apos;s existing integration.", "source": "NHS England, December 2025", "url": "https://www.england.nhs.uk/2025/12/record-numbers-using-nhs-app-to-manage-health/"}, "hannah-s6": {"who": "Hannah", "role": "GP partner", "img": "hannah", "say": "Three hundred and seven million general-practice sessions a year. One in twenty missed. Take routine monitoring out of the queue and the access targets can finally breathe. The practice nurse is doing the work she should always have been doing.", "stat": "~307 million general-practice sessions are scheduled annually in England; around 5% are missed.", "source": "NHS England, 2019", "url": "https://www.england.nhs.uk/2019/01/missed-gp-appointments-costing-nhs-millions/"}, "abdul-s1": {"who": "Sarah", "role": "Commissioner", "img": "sarah", "say": "Somewhere out there are 4.2 million people, England-wide, with high blood pressure nobody has found. Abdul found his own with his phone. That is a stroke I never have to commission.", "stat": "An estimated 4.2 million adults in England have undiagnosed high blood pressure; hypertension is implicated in around half of all heart attacks and strokes.", "source": "NHS England / ONS, 2025", "url": "https://www.england.nhs.uk/north-west/2025/09/04/are-you-one-of-the-missing-millions-get-your-blood-pressure-checked-this-know-your-numbers-week/"}, "abdul-s2": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "Thirty-nine million people already carry the front door in their pocket. I don't have to build Abdul a platform. I have to plug the kit into the one he already uses.", "stat": "39 million people are registered on the NHS App, with 62.3 million logins in a single month.", "source": "NHS England, December 2025", "url": "https://www.england.nhs.uk/2025/12/record-numbers-using-nhs-app-to-manage-health/"}, "abdul-s3": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "Capillary lipid testing has been validated for years. The clinical question was never the science. It was the venue and the assurance chain. Both now sit in the framework.", "stat": "Capillary blood testing for lipid and HbA1c panels is validated under UKAS-accredited labs and CE-marked devices; routine monitoring is established practice.", "source": "UKAS ISO 15189; MHRA IVD framework"}, "abdul-s4": {"who": "Hannah", "role": "GP", "img": "hannah", "say": "When Abdul's result lands with me, the conversation is the same conversation. Lifestyle, statin if indicated, follow-up. The venue of the blood draw never changed the clinical decision.", "stat": "NICE CG181 sets prescribing thresholds for statin therapy in primary cardiovascular prevention; the clinical pathway is unchanged by home-test sampling.", "source": "NICE CG181", "url": "https://www.nice.org.uk/guidance/cg181"}, "abdul-s5": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "Threshold alerts replace periodic reviews. My attention goes where the readings say, not where the diary says.", "stat": "Follow-up appointments account for 54% of NHS outpatient activity in England, much of it judged of limited clinical value.", "source": "GIRFT / NHS England outpatient improvement guide", "url": "https://gettingitrightfirsttime.co.uk/cross_cutting_theme/further-faster-programme/"}, "mark-s1": {"who": "Adam", "role": "Consultant urologist", "img": "adam", "say": "Prostate cancer is now the UK's most common cancer, more than sixty-four thousand men a year, and every one of them lands on a list like mine. The list grows. My clinic does not.", "stat": "64,000+ men diagnosed with prostate cancer in the UK per year (2022 data); around 6,500 a year choose active surveillance, with up to 5,000 more who could.", "source": "Prostate Cancer UK, 2026", "url": "https://prostatecanceruk.org/about-us/news-and-views/2026/01/prostate-most-common-cancer", "source2": "Prostate Cancer UK / NHS data, 2025", "url2": "https://prostatecanceruk.org/about-us/news-and-views/2025/08/active-surveillance-unnecessary-treatment"}, "mark-s2": {"who": "Catherine", "role": "Acute Trust commissioner", "img": "catherine", "say": "Follow-ups are fifty-four per cent of everything my outpatient budget buys. Mark's routine PSA is precisely the kind of follow-up that never needed a room.", "stat": "Follow-up appointments represent 54% of NHS outpatient activity; standardised templates and remote models could unlock 1-2 million slots.", "source": "GIRFT, Further Faster programme", "url": "https://gettingitrightfirsttime.co.uk/cross_cutting_theme/further-faster-programme/"}, "mark-s3": {"who": "Joe", "role": "Supplier", "img": "joe", "say": "One and a quarter billion pathology requests this year, growing five and a half per cent annually. Buildings can't absorb that curve. Kit out, post back, lab capacity where it's actually elastic.", "stat": "NHS pathology test requests projected at 1.25bn for 2025/26 (730m in 2013/14), growing ~5.5% a year.", "source": "NHS national programme analysis, 2026"}, "mark-s4": {"who": "Adam", "role": "Consultant urologist", "img": "adam", "say": "The surveillance is the treatment. The clinical work is reading the trend. Mark's home result lands on my desk with everything that came before it, in the same review I would have run in clinic.", "stat": "NICE NG131 sets the active surveillance protocol; threshold breaches trigger MDT review and repeat imaging on a defined cycle.", "source": "NICE NG131", "url": "https://www.nice.org.uk/guidance/ng131"}, "mark-s5": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "The silence is doing clinical work. Every result is reviewed in trend, and escalation happens when the line moves. Safety is the review, not the appointment.", "stat": "England booked 135.4 million outpatient appointments in 2023/24; routine surveillance bloods need not be among them.", "source": "NHS Digital, Hospital Outpatient Activity 2023-24", "url": "https://digital.nhs.uk/data-and-information/publications/statistical/hospital-outpatient-activity/2023-24"}, "layla-s1": {"who": "Hannah", "role": "GP", "img": "hannah", "say": "Iron-deficiency anaemia touches around eight per cent of adult women. The monitoring is one blood tube on a six-month clock. The clock was never the problem. The clinic was.", "stat": "Iron deficiency anaemia prevalence in the UK is around 3% of adult men and 8% of adult women; guidelines monitor treatment response by FBC.", "source": "NICE clinical knowledge summary", "url": "https://cks.nice.org.uk/topics/anaemia-iron-deficiency/"}, "layla-s2": {"who": "Anita", "role": "ICB / GP commissioner", "img": "anita", "say": "Fifteen million missed GP-practice appointments a year, two hundred and sixteen million pounds, and the system writes DNA as if it were her fault. Layla wasn't refusing care. She was keeping her job.", "stat": "Around 15 million general-practice appointments are missed each year, costing the NHS £216m (average ~£30 per missed GP appointment).", "source": "NHS England, 2019", "url": "https://www.england.nhs.uk/2019/01/missed-gp-appointments-costing-nhs-millions/"}, "layla-s3": {"who": "Ngozi", "role": "Information Governance", "img": "ngozi", "say": "The result lands in her GP record, not in a silo, the same governance as any practice bloods. The kit changes the venue. It never changes the protections.", "stat": "DPIA, data-sharing and processing agreements are executed before go-live; the result flows to the GP record under the practice's existing controllership.", "source": "Service IG framework (executed pre-go-live)"}, "layla-s4": {"who": "Hannah", "role": "GP", "img": "hannah", "say": "Same clinical decision, same accountability, different venue for the blood. The medicine was always in primary care. What changed is that the trend was still readable when the dose needed to move.", "stat": "NICE guidelines on Iron deficiency anaemia treatment are unchanged by sample-venue; iron supplementation is titrated to FBC response.", "source": "NICE clinical knowledge summary", "url": "https://cks.nice.org.uk/topics/anaemia-iron-deficiency/"}, "layla-s5": {"who": "Anita", "role": "ICB / GP commissioner", "img": "anita", "say": "Three hundred and seven million general-practice appointments a year, and one in twenty missed. Take even the routine bloods out of that queue and my access targets can finally breathe.", "stat": "~307 million general-practice sessions are scheduled annually in England; around 5% are missed without enough notice to rebook.", "source": "NHS England, 2019", "url": "https://www.england.nhs.uk/2019/01/missed-gp-appointments-costing-nhs-millions/"}, "sean-s1": {"who": "Hannah", "role": "GP", "img": "hannah", "say": "I run the annual health checks, uptake is nearly eighty per cent now. And still, people with a learning disability die a median nineteen and a half years younger than everyone else. The check exists because the gap is real. The bloods are where it stalls.", "stat": "79.9% of people on the learning disability register had an annual health check (March 2025); median age of death is 62.3 years, about 19.5 years younger than the general population.", "source": "NHS England; LeDeR annual report 2023 (pub. 2025)", "url": "https://www.england.nhs.uk/learning-disabilities/improving-health/learning-from-lives-and-deaths/"}, "sean-s2": {"who": "His brother", "role": "Family", "img": null, "say": "Easy-read isn't a kindness we're asking for. It has been a legal duty since 2016. The Accessible Information Standard says information must work for the person it's about. For Sean, pictures work.", "stat": "The Accessible Information Standard has been a legal requirement for NHS and adult social care providers since 2016.", "source": "NHS England, Accessible Information Standard", "url": "https://www.england.nhs.uk/ourwork/accessibleinfo/"}, "sean-s3": {"who": "Ngozi", "role": "Information Governance", "img": "ngozi", "say": "The reasonable-adjustment flag exists nationally so Sean's needs travel with his record. Honouring it at the ordering step is the difference between a policy and a practice.", "stat": "The Reasonable Adjustment Digital Flag is a national NHS record flag enabling adjustments to be known across services.", "source": "NHS England, Reasonable Adjustment Digital Flag", "url": "https://www.england.nhs.uk/learning-disabilities/improving-health/reasonable-adjustments/"}, "sean-s4": {"who": "Hannah", "role": "GP", "img": "hannah", "say": "The treatment was never different for Sean. The wrap-around was. Easy-read prescribing, the support worker in the loop, the brother holding the calendar. That is what made the treatment actually take.", "stat": "Reasonable adjustments under the Equality Act 2010 require services to anticipate and meet the access needs of disabled patients across treatment as well as referral.", "source": "NHS England, Reasonable Adjustment Digital Flag; Equality Act 2010"}, "sean-s5": {"who": "Sarah", "role": "Commissioner", "img": "sarah", "say": "Thirty-nine per cent of the deaths reviewed were judged avoidable. Avoidable is a commissioning word. Reach is the lever I hold, and this is what reach looks like.", "stat": "39% of reviewed deaths of people with a learning disability were assessed as avoidable (down from 46% in 2021).", "source": "LeDeR annual report 2023 (pub. 2025)", "url": "https://www.england.nhs.uk/learning-disabilities/improving-health/learning-from-lives-and-deaths/"}, "joe-s2": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "Old price of bidding for NHS work was paying for the privilege of finding out what was wanted. New price is reading the criteria pack on Future NHS and deciding whether you fit. The door is open before you ask.", "stat": "The Procurement Act 2023 commenced 24 February 2024 and establishes streamlined dynamic-market routes for assured supplier admission; bespoke open-procedure procurement of a new service typically takes 6-9 months at minimum.", "source": "UK Government, PA23 guidance", "url": "https://www.gov.uk/government/collections/the-procurement-act-2023-guidance-documents"}, "joe-s3a": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "A structured EOI is a small commitment that does big reading. Same shape every time, same questions, same evidence references. We can compare suppliers fairly because we are reading the same form, not five different essays.", "stat": "Atamis is the NHS England-wide procurement platform; structured submissions on a common platform support consistent intake, evaluation and audit trail across NHS procurements.", "source": "NHS England Commercial / Atamis", "url": "https://www.atamis.co.uk/"}, "joe-s3b": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "Joe&apos;s submission lands in the same tenancy as every other admitted supplier. The evidence references attach to the artefact catalogue we already maintain. Nothing has to be invented to receive him. The rails were already there.", "stat": "Framework intake on a single procurement platform reduces variance in evaluation and creates a single audit trail per supplier across multiple call-offs.", "source": "NHS England Commercial / Atamis", "url": "https://www.atamis.co.uk/"}, "joe-s4a": {"who": "Ngozi", "role": "Information Governance", "img": "ngozi", "say": "The DPIA is one template. I review the pattern once, not five times because five LAs each want their own. The supplier inherits the template, the LA confirms its controllership, the protections are the same across every deployment.", "stat": "UK GDPR Article 35 requires a DPIA for processing likely to result in high risk; a single template executed centrally and inherited at LA-level removes duplicated assessment without weakening the protections.", "source": "UK GDPR Article 35; ICO DPIA guidance", "url": "https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/"}, "joe-s4b": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "DCB0129 sits with the platform manufacturer and is portable across configurations once Joe&apos;s API is evidenced. DCB0160 sits with whoever operates the service locally. The framework pre-fabs the deployment artefacts so the local body amends and signs the local context, instead of authoring the safety case from scratch.", "stat": "DCB0129 (manufacturer clinical risk management) sits with the platform manufacturer. DCB0160 (deployment safety) sits with the operating organisation (LA, Trust or supplier-as-managed-service depending on local arrangement). Centre-led artefact pre-fab is the agreed scaling pattern.", "source": "NHS Digital DCB0129 / DCB0160", "url": "https://digital.nhs.uk/services/clinical-safety"}, "joe-s4c": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "The conformance certificate is the contract carrier. Every commissioner calling Joe off reads the same evidence pack, signs the same call-off, runs the same terms. Three months of bilateral legal negotiation per LA disappears. That is the saving the framework is meant to deliver.", "stat": "Inherited framework call-off mechanisms typically reduce contract-to-service-launch timing from 6-9 months bespoke to a matter of weeks per call-off.", "source": "NHS SBS framework call-off guidance (timing reflects commercial-experience baseline; specific durations not published on the SBS frameworks page)"}, "joe-s4d": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "Joe integrates once to the platform. That integration sits at API-level. Every test he adds under it is a configuration, not a build. Every commissioner he serves through it inherits the same rails. The platform is the singular asset the framework rests on.", "stat": "Single-API integration with downstream configuration variance is the modern NHS platform pattern (e.g. NHS App, EPS); per-test bespoke integration is the legacy alternative.", "source": "NHS Digital architecture patterns / API catalogue", "url": "https://digital.nhs.uk/developer/api-catalogue"}, "joe-s5": {"who": "Sarah", "role": "LA sexual health commissioner", "img": "sarah", "say": "My job is to commission the service for my cohort. It is not to re-assure that a framework-admitted supplier is safe. The conformance certificate is the trust marker. My first question to Joe was when can we go live, not whether we should.", "stat": "Late HIV diagnosis (CD4 <350) accounts for around 40% of new HIV diagnoses in England; commissioning speed is one of the levers that closes the gap.", "source": "UKHSA, HIV in England Annual Report", "url": "https://www.gov.uk/government/publications/hiv-in-england-annual-report"}, "joe-s6a": {"who": "Ngozi", "role": "Information Governance", "img": "ngozi", "say": "Joe is reused across three conditions and six commissioners without a fresh DPIA at each step. The annual refresh is when I look again, not every call-off. That is what onboard-once means in practice from where I sit.", "stat": "DPIA review is required where processing materially changes; an annual refresh cycle aligns with ICO guidance for stable processing activities.", "source": "ICO DPIA guidance", "url": "https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/accountability-and-governance/data-protection-impact-assessments-dpias/"}, "joe-s6b": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "Each new commissioner calling Joe off is a call-off, not a tender. The framework holds the standing terms. The deployment is the business. That is the unit economics the framework was designed to unlock for smaller suppliers.", "stat": "Framework call-off mechanisms reduce per-deployment legal and assurance cost to a small fraction of bespoke procurement, supporting market participation by smaller suppliers.", "source": "NHS SBS framework guidance (timing reflects commercial-experience baseline; specific durations not published on the SBS frameworks page)"}, "catherine-s1": {"who": "Adam", "role": "Consultant urologist", "img": "adam", "say": "Prostate cancer is the UK's most common cancer now, more than sixty-four thousand men a year, and the active-surveillance cohort only grows. Catherine's monitoring caseload is real men on my lists. The clinic cannot hold all of them in a room.", "stat": "64,000+ men are diagnosed with prostate cancer in the UK each year (2022 data); around 6,500 a year choose active surveillance, with up to 5,000 more who could.", "source": "Prostate Cancer UK, 2026", "url": "https://prostatecanceruk.org/about-us/news-and-views/2026/01/prostate-most-common-cancer", "source2": "Prostate Cancer UK / NHS data, 2025", "url2": "https://prostatecanceruk.org/about-us/news-and-views/2025/08/active-surveillance-unnecessary-treatment"}, "catherine-s2": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "The old price of standing up a monitoring pathway was a clean-sheet procurement. Catherine opens an admitted framework instead. Suppliers listed, call-off terms published, safety-case and IG templates ready. The price of entry is a signature, not a discovery exercise.", "stat": "Bespoke open-procedure procurement of a new service typically takes 6-9 months at minimum; call-off against an inherited national framework typically completes in weeks.", "source": "NHS SBS framework guidance (timing reflects commercial-experience baseline; specific durations not published on the SBS frameworks page)"}, "catherine-s3": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "The clinical authority does not move. Capillary PSA returns to the consultant urologist first, in trend, with thresholds wired to NICE NG131, and the clinical safety case is executed before go-live. The kit changes the venue of the blood, not the decision.", "stat": "NICE NG131 covers PSA testing thresholds and active-surveillance triggers; the clinical safety case (DCB0129 / DCB0160) is executed pre-go-live for the configuration.", "source": "NICE NG131; NHS Digital DCB0129 / DCB0160", "url": "https://www.nice.org.uk/guidance/ng131"}, "catherine-s4": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "An ICB mandate route into her Trust partners, not an external tender. Six weeks from brief to first live Trust, payment on published call-off terms. The procurement scar she carried in is not the arrangement she signed.", "stat": "Inherited framework call-off mechanisms typically reduce contract-to-service-launch timing from 6-9 months bespoke to a matter of weeks per call-off.", "source": "NHS SBS framework call-off guidance (timing reflects commercial-experience baseline; specific durations not published on the SBS frameworks page)"}, "catherine-s5": {"who": "Adam", "role": "Consultant urologist", "img": "adam", "say": "The surveillance is the treatment and the clinical work is reading the trend. Follow-ups are more than half of everything the outpatient budget buys, and a routine PSA is exactly the follow-up that never needed a room. My clinic now holds the patients whose disease behaviour says clinic is the right venue.", "stat": "Follow-up appointments account for 54% of NHS outpatient activity in England; 8.0 million appointments went unattended in 2023/24, of 135.4 million booked.", "source": "GIRFT / NHS England outpatient improvement guide; NHS Digital Hospital Outpatient Activity 2023-24", "url": "https://gettingitrightfirsttime.co.uk/cross_cutting_theme/further-faster-programme/"}, "catherine-s6": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "What the CMO sees is one MI feed and one cohort view, because the integration happened once, nationally. Catherine's Trusts did not each build a special interface. Her men walked in through a front door thirty-nine million people already use.", "stat": "39 million people are registered on the NHS App, with 62.3 million logins in a single month; result write-back to the Trust EPR is part of the inherited platform integration.", "source": "NHS England, December 2025", "url": "https://www.england.nhs.uk/2025/12/record-numbers-using-nhs-app-to-manage-health/"}, "anita-s1": {"who": "Hannah", "role": "GP partner", "img": "hannah", "say": "Anita's at-risk register runs into the tens of thousands, and it keeps growing. More than three and a half million people now sit on GP non-diabetic-hyperglycaemia registers in England, up almost a fifth in a year. The ones the register serves worst are the ones who cannot get to the clinic.", "stat": "3,615,330 people were recorded with non-diabetic hyperglycaemia on GP registers in England in 2023, up 18% on 2022; around 1 in 9 adults in England are affected.", "source": "National Diabetes Audit / Diabetes UK, 2024", "url": "https://www.diabetes.org.uk/about-us/news-and-views/one-five-adults-now-live-diabetes-or-prediabetes-uk"}, "anita-s2": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "Anita opens an admitted framework, not a clean-sheet procurement. The HbA1c configuration is live, suppliers are listed on published call-off terms, and the QOF-linkage templates are ready. Her question is which configuration, not which procurement.", "stat": "Bespoke open-procedure procurement of a new service typically takes 6-9 months at minimum; call-off against an inherited national framework typically completes in weeks.", "source": "NHS SBS framework guidance (timing reflects commercial-experience baseline; specific durations not published on the SBS frameworks page)"}, "anita-s3": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "Capillary HbA1c is held to DCCT-aligned analytical performance, the same standard as the practice's venous samples. Forty-two to forty-seven flags non-diabetic hyperglycaemia; forty-eight on a repeat confirms diabetes. The decision thresholds do not move because the sample came from a kitchen table.", "stat": "HbA1c of 42-47 mmol/mol identifies non-diabetic hyperglycaemia; 48 mmol/mol (6.5%) or above on a repeat sample confirms type 2 diabetes.", "source": "WHO 2011 HbA1c diagnostic criteria, adopted by NICE"}, "anita-s4": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "One call-off, every practice in the ICB plugging into a common schedule, QOF-linked where it applies. Six weeks from brief to first live practice, not eighteen months. That is what the framework is for.", "stat": "Inherited framework call-off mechanisms typically reduce contract-to-service-launch timing from 6-9 months bespoke to a matter of weeks per call-off.", "source": "NHS SBS framework call-off guidance (timing reflects commercial-experience baseline; specific durations not published on the SBS frameworks page)"}, "anita-s5": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "The result rides the same rails as any other blood: back to the GP record, in trend, with QOF DM006 auto-linkage. No parallel system, no clerk in the loop. Thirty-nine million people are already on the NHS App; the patient just sees the kit.", "stat": "39 million people are registered on the NHS App, with 62.3 million logins in a single month; result write-back to the GP record is via the framework's existing integration.", "source": "NHS England, December 2025", "url": "https://www.england.nhs.uk/2025/12/record-numbers-using-nhs-app-to-manage-health/"}, "anita-s6": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "The prevention pathway works when you can keep the at-risk cohort in view. The NHS Diabetes Prevention Programme cut type 2 incidence by more than a third in the people who completed it. Home HbA1c is how you find the drift early enough to refer them in time.", "stat": "An independent evaluation of the NHS Diabetes Prevention Programme found a 37% relative reduction in type 2 diabetes incidence among completers and a 7% reduction at population level.", "source": "DIPLOMA evaluation; NHS England Diabetes high impact interventions", "url": "https://www.england.nhs.uk/ourwork/prevention/secondary-prevention/diabetes-high-impact-interventions/"}, "devi-s1": {"who": "Hannah", "role": "GP partner", "img": "hannah", "say": "The cohort I lose is the cohort most at risk. Black and South Asian patients are two to four times more likely to develop type 2 diabetes, and it starts younger, from around twenty-five. Devi is exactly who the register is for, and exactly who a mid-week clinic slot fails.", "stat": "Black and South Asian people are two to four times more likely to develop type 2 diabetes than White people; risk rises from around age 25 rather than 40.", "source": "Diabetes UK", "url": "https://www.diabetes.org.uk/about-diabetes/type-2-diabetes/diabetes-ethnicity"}, "devi-s2": {"who": "Anita", "role": "ICB / GP commissioner", "img": "anita", "say": "Fifteen million missed general-practice appointments a year, two hundred and sixteen million pounds, and the system records DNA as if it were her fault. Devi was not refusing care. She was keeping her job. The flag on her record is a venue problem, not a compliance problem.", "stat": "Around 15 million general-practice appointments are missed each year, costing the NHS £216m (average ~£30 per missed GP appointment).", "source": "NHS England, 2019", "url": "https://www.england.nhs.uk/2019/01/missed-gp-appointments-costing-nhs-millions/"}, "devi-s3": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "The Saturday-morning sample is held to the same DCCT-aligned standard as the practice's venous bloods. The result lands in Hannah's system in time for the review the clinic would have run. The science was never the barrier. The venue was.", "stat": "Capillary HbA1c on a DCCT-aligned assay platform is held to the same analytical performance standard as venous samples; HbA1c is the established measure for glycaemic surveillance.", "source": "WHO 2011 HbA1c diagnostic criteria, adopted by NICE; IFCC standardisation"}, "devi-s4": {"who": "Hannah", "role": "GP partner", "img": "hannah", "say": "At forty-four the plan stands and the next review is twelve months out. A drift into the mid-forties is when I want the conversation and a prevention-programme referral, and the evidence says that referral matters: completers cut their diabetes risk by more than a third. The home result is what lets me catch the drift in time.", "stat": "The NHS Diabetes Prevention Programme achieved a 37% relative reduction in type 2 diabetes incidence among completers; referral is triggered by HbA1c in the non-diabetic hyperglycaemia range (42-47 mmol/mol).", "source": "DIPLOMA evaluation; NHS England Diabetes high impact interventions", "url": "https://www.england.nhs.uk/ourwork/prevention/secondary-prevention/diabetes-high-impact-interventions/"}, "devi-s5": {"who": "Anita", "role": "ICB / GP commissioner", "img": "anita", "say": "Devi stays in the cycle, and that is the whole point. Of the first hundred thousand people referred to the prevention programme, only just over half attended the first assessment. The ones who fall out are the ones the clinic was always going to lose. Home testing is how you hold the cohort the system quietly drops.", "stat": "Of the first 100,000 referrals to the NHS Diabetes Prevention Programme from primary care, just over half attended the initial assessment.", "source": "NHS Diabetes Prevention Programme uptake evaluation", "url": "https://www.ncbi.nlm.nih.gov/pmc/articles/PMC10091609/"}, "ruth-s1": {"who": "Adam", "role": "Consultant urologist", "img": "adam", "say": "Many of the men I see with a raised PSA do not have cancer. I still cannot discharge them into nothing. Ruth&apos;s cohort is the men my clinic has assessed and cannot keep, and until now nobody held the list.", "stat": "Many men with a raised PSA level do not have prostate cancer. Where a GP thinks something other than cancer has raised the level, the usual advice is a repeat PSA test in the future to see whether it changes, rather than immediate referral. Normal PSA is usually below 3 ng/ml, varying with age and other factors.", "source": "Prostate Cancer UK, the PSA blood test", "url": "https://prostatecanceruk.org/prostate-information-and-support/prostate-tests/psa-blood-test", "source2": "NHS website, PSA test (reviewed September 2024)", "url2": "https://www.nhs.uk/tests-and-treatments/psa-test/"}, "ruth-s2": {"who": "Joe", "role": "Supplier", "img": "joe", "say": "I passed company assurance once, on the Master SCAL, and PSA conformance once for the category. Whoever Ruth turns out to be, she buys from the same register I am already on. Her cohort is new. My paperwork is not.", "stat": "Tier 1 company assurance is passed once through the Master SCAL; Tier 2 conformance is passed per test category, with UKAS-accredited labs and MHRA-conformant kits added by the framework. The framework holds an Any Qualified Provider floor of around three suppliers per test category, in principle.", "source": "HomeTest Supplier Onboarding Framework and Commercial Model (positions in principle)", "url": "DTx OM - Supplier Onboarding Framework.html"}, "ruth-s3": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "The platform can run annual, biannual, risk-stratified or symptom-led recall. It will not choose for the urologists. Until a protocol is signed against NG131 and the safety case is executed, nothing goes live for this cohort, and that is the right order.", "stat": "NICE NG131 covers PSA testing thresholds and active-surveillance triggers; the clinical safety case (DCB0129 / DCB0160) is executed before go-live for each configuration.", "source": "NICE NG131; NHS Digital DCB0129 / DCB0160", "url": "https://www.nice.org.uk/guidance/ng131"}, "ruth-s4": {"who": "David", "role": "NHS Commercial", "img": "david", "say": "Whichever budget this lands in, the terms are the ones already on the framework: a cost per activity for each completed test against a national ceiling, a levy on throughput with a share back to NHS England, and a call-off rather than a procurement. The paying party is the only blank on the form.", "stat": "Commercial positions agreed in principle: a cost per activity for each completed test against a national ceiling that local competition can beat; a levy on throughput that funds the platform with a share returned to NHS England; commissioners call off from the accredited register rather than running their own procurement. All subject to the live procurement.", "source": "HomeTest Commercial Model: How Commissioners Buy and Money Loop", "url": "DTx OM - How Commissioners Buy.html"}, "ruth-s5": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "Her men come through the same front door thirty-nine million people already use. Enrolment, recall, result and escalation are platform events, so a missed recall is an exception I can show her, not a silence nobody owns.", "stat": "39 million people are registered on the NHS App, with 62.3 million logins in a single month; result write-back is part of the inherited platform integration.", "source": "NHS England, December 2025", "url": "https://www.england.nhs.uk/2025/12/record-numbers-using-nhs-app-to-manage-health/"}, "ruth-s6": {"who": "Anita", "role": "ICB / GP commissioner", "img": "anita", "say": "Ruth is not asking anyone to pick a new test. PSA active surveillance was scored and selected in June; her cohort rides a configuration that already exists. The case she has to make is the funding one, and for the first time the platform gives her the numbers to make it.", "stat": "PSA active surveillance scored 35/45 (Priority 2, next wave) under the HomeTest Prioritisation Framework and is the board-selected acute use case, endorsed in principle at the HomeTest Programme Board on 9 June 2026. The monitoring-gap sub-cohort sits under that configuration score rather than being scored separately.", "source": "HomeTest Prioritisation Framework; Pathway 2 Discovery matrix", "url": "DTx OM - Prioritisation Framework.html"}, "pauline-s1": {"who": "Ravi", "role": "Prescribing clinician", "img": "ravi", "say": "I prescribe it the way I prescribe an inhaler: from a formulary, against her care plan, on her record. NICE has already looked at this class of technology for exactly her cohort, so the conversation in clinic is about Pauline, not about whether apps are allowed.", "stat": "NICE early value assessments HTG736 (digital technologies to support self-management of COPD, December 2024, updated September 2025) and HTG718 (digital technologies to deliver pulmonary rehabilitation for adults with COPD, April 2024, updated September 2025) conditionally recommend the technology classes the HealthStore COPD Alpha draws on while further evidence is generated. Together they replaced the earlier myCOPD guidance (MTG68).", "source": "NICE HTG736", "url": "https://www.nice.org.uk/guidance/htg736", "source2": "NICE HTG718", "url2": "https://www.nice.org.uk/guidance/htg718"}, "pauline-s2": {"who": "Priya", "role": "NHSE Platform", "img": "priya", "say": "She did not download anything. The prescription unlocked the therapeutic inside the app her daughter set up, under NHS Login, with the NHS holding the record. Thirty-nine million people already carry that front door; my job was to make sure the supplier&apos;s programme appeared behind it.", "stat": "39 million people are registered on the NHS App, with 62.3 million logins in a single month. The digital therapeutic is a third-party product surfaced inside the NHS App under NHS Login, with the NHS as custodian of the record.", "source": "NHS England, December 2025", "url": "https://www.england.nhs.uk/2025/12/record-numbers-using-nhs-app-to-manage-health/"}, "pauline-s3": {"who": "Daniel", "role": "ICB commissioner", "img": "daniel", "say": "A rehab class twelve miles away is a programme she would not have finished. Ninety per cent of people who complete pulmonary rehabilitation move more and feel better, so my job is to make completion the default. The wrapper around the therapeutic is how.", "stat": "90 per cent of patients who complete a pulmonary rehabilitation programme have higher activity and exercise levels and report an improved quality of life. A course typically runs six to eight weeks with two sessions a week, and PR is shown to reduce exacerbations, acute and emergency admissions and primary care appointments. Respiratory disease is a clinical priority in the NHS Long Term Plan.", "source": "NHS England, Pulmonary rehabilitation (clinical policy)", "url": "https://www.england.nhs.uk/ourwork/clinical-policy/respiratory-disease/pulmonary-rehabilitation/"}, "pauline-s4": {"who": "Aisha", "role": "Clinical / CSG", "img": "aisha", "say": "The therapeutic does not treat the exacerbation. It sees the trend a week before she would have rung anyone and lands a structured escalation on her record. The trigger belongs to the care plan, the safety case is executed before go-live, and a clinician still makes the call.", "stat": "NICE NG115 sets out self-management and exacerbation action plans for people with COPD; the digital therapeutic&apos;s escalation trigger is defined by the care plan, and the clinical safety case (DCB0129 / DCB0160) is executed before go-live.", "source": "NICE NG115; NHS Digital DCB0129 / DCB0160", "url": "https://www.nice.org.uk/guidance/ng115"}, "pauline-s5": {"who": "Daniel", "role": "ICB commissioner", "img": "daniel", "say": "I buy the episode, in principle on pathway-level terms rather than per download. What comes back to me is adherence, symptom trajectory and escalations, per patient and in aggregate. That is the value case, and it holds because the engagement behind it is real.", "stat": "DDTx 26/27 outcomes for HealthStore include supporting over 6,000 existing COPD-app patients through the HealthStore product model, partnering with two ICBs that already commission COPD management apps, and a Private Beta launch for three use cases (COPD, cardiac rehabilitation, insomnia). The marketplace payments mechanism (start, meaningful engagement, completion, outcome capture) is being designed in Alpha; commercial positions are in principle.", "source": "DDTx 26/27 outcomes, Digital Therapeutics Operating Model Lifecycle; HealthStore product overlay", "url": "DTx OM - Lifecycle.html"}};
var css = ".hm-witness{position:relative;display:inline-block;vertical-align:middle;margin-left:10px;}"+
".hmw-chip{width:38px;height:38px;border-radius:50%;border:2.5px solid #FFB91D;background:#fff;cursor:pointer;padding:0;overflow:hidden;box-shadow:0 3px 10px rgba(0,32,64,0.22);display:inline-flex;align-items:center;justify-content:center;transition:transform .15s ease;}"+
".hmw-chip:hover{transform:scale(1.12);}"+
".hmw-chip img{width:100%;height:100%;object-fit:cover;object-position:top center;display:block;}"+
".hmw-chip .hmw-init{font:800 15px 'Segoe UI',sans-serif;color:#003087;}"+
".hmw-card{position:absolute;top:46px;left:50%;transform:translateX(-50%);width:330px;max-width:82vw;background:#fff;border:1px solid #d6e2ef;border-top:4px solid #FFB91D;border-radius:12px;box-shadow:0 16px 40px rgba(0,32,64,0.25);padding:16px 18px;z-index:500;display:none;text-align:left;}"+
".hm-witness.open .hmw-card,.hm-witness:hover .hmw-card{display:block;}"+
".hmw-head{display:flex;align-items:center;gap:10px;margin-bottom:9px;}"+
".hmw-head img{width:34px;height:34px;border-radius:50%;object-fit:cover;object-position:top center;}"+
".hmw-name{font:800 13px 'Segoe UI',sans-serif;color:#003087;}"+
".hmw-role{font:700 9px 'Segoe UI',sans-serif;color:#7E8B97;letter-spacing:1px;text-transform:uppercase;}"+
".hmw-say{font:italic 600 13px 'Segoe UI',sans-serif;color:#212B32;line-height:1.5;margin-bottom:9px;}"+
".hmw-stat{font:600 11.5px 'Segoe UI',sans-serif;color:#4C6272;line-height:1.5;background:#F4F8FC;border-left:3px solid #005EB8;padding:8px 10px;border-radius:0 8px 8px 0;margin-bottom:8px;}"+
".hmw-src{font:600 9px 'Segoe UI',sans-serif;color:#7E8B97;letter-spacing:0.4px;}"+
".hmw-link{display:inline-block;margin-top:7px;font:800 10.5px 'Segoe UI',sans-serif;color:#005EB8;text-decoration:none;}"+
".hmw-card.pin-right{left:auto;right:0;transform:none;}"+
".hmw-card.pin-left{left:0;right:auto;transform:none;}";
var st = document.createElement("style"); st.textContent = css; document.head.appendChild(st);
document.querySelectorAll(".hm-witness[data-moment]").forEach(function(el){
  var m = M[el.getAttribute("data-moment")]; if(!m) return;
  var chip = document.createElement("button"); chip.className = "hmw-chip";
  chip.setAttribute("aria-label", m.who + " — their view of this moment");
  chip.innerHTML = m.img ? '<img src="' + IMG + m.img + '.png" alt="' + m.who + '">' : '<span class="hmw-init">' + m.who.charAt(0) + '</span>';
  if (m.img) { var ci = chip.querySelector("img"); ci.addEventListener("error", function(){ chip.innerHTML = '<span class="hmw-init">' + m.who.charAt(0) + "</span>"; }); }
  var card = document.createElement("div"); card.className = "hmw-card";
  var link = (m.img && PERSONA[m.img]) ? '<a class="hmw-link" href="' + PERSONA[m.img] + '">' + m.who + "&rsquo;s page &rarr;</a>" : "";
  card.innerHTML = '<div class="hmw-head">' + (m.img ? '<img src="' + IMG + m.img + '.png" alt="" onerror="this.remove()">' : "") +
    '<div><div class="hmw-name">' + m.who + '</div><div class="hmw-role">' + m.role + "</div></div></div>" +
    '<div class="hmw-say">&ldquo;' + m.say + '&rdquo;</div>' +
    '<div class="hmw-stat">' + m.stat + '</div>' +
    '<div class="hmw-src">Source: ' + (m.url ? '<a href="' + m.url + '" target="_blank" rel="noopener" style="color:#005EB8;text-decoration:underline;">' + m.source + "</a>" : m.source) + (m.url2 ? ' &middot; <a href="' + m.url2 + '" target="_blank" rel="noopener" style="color:#005EB8;text-decoration:underline;">' + m.source2 + "</a>" : (m.source2 ? " &middot; " + m.source2 : "")) + "</div>" + link;
  el.appendChild(chip); el.appendChild(card);
  function place(){
    card.classList.remove("pin-right","pin-left");
    var wasHidden = getComputedStyle(card).display === "none";
    if (wasHidden){ card.style.visibility = "hidden"; card.style.display = "block"; }
    var bound = el.closest(".page") || document.documentElement;
    var br = bound.getBoundingClientRect();
    var r = card.getBoundingClientRect();
    if (wasHidden){ card.style.display = ""; card.style.visibility = ""; }
    var pad = 14;
    if (r.right > br.right - pad) card.classList.add("pin-right");
    else if (r.left < br.left + pad) card.classList.add("pin-left");
  }
  el.addEventListener("mouseenter", place);
  chip.addEventListener("click", function(e){ e.stopPropagation(); e.preventDefault();
    document.querySelectorAll(".hm-witness.open").forEach(function(o){ if(o!==el) o.classList.remove("open"); });
    el.classList.toggle("open"); if (el.classList.contains("open")) place(); });
});
document.addEventListener("click", function(){ document.querySelectorAll(".hm-witness.open").forEach(function(o){ o.classList.remove("open"); }); });
})();
